/*
 * dir/test/test_dir_data.c - the DIR module block DIR_$DATA, 0x00E7DBF8+0x212C
 *
 * (block tests: Generated by: Claude Opus 5.5, source-qiby)
 *
 * The block laid over its image address pins every map symbol, the A5 base
 * and the bias arms, and its contents are the image's non-zero bytes.  Two
 * more things the image pins and nothing else in dir/ asserts:
 *   - DIR_$OP_TAB is one *biased* table.  Every reader indexes it by
 *     (opcode >> 1) from a virtual base of 0x00E7FB9A, which is 21 records
 *     below the array; only records 21..46 (opcodes 0x2A..0x5C, the range
 *     DIR_$DO_OP's jump table admits) are physically present.
 *   - the last 0x12 bytes of the segment, 0x00E7FD12..0x00E7FD24.
 */

#include "dir/dir_internal.h"

#include "../dir_data.c"

#include <stdio.h>
#include <string.h>

static int tests_run = 0;
static int tests_failed = 0;
static int current_failed;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name)                                                        \
    do {                                                                      \
        current_failed = 0;                                                   \
        tests_run++;                                                          \
        test_##name();                                                        \
        printf("%-48s %s\n", #name, current_failed ? "FAIL" : "ok");          \
    } while (0)
#define ASSERT_EQ(expected, actual)                                           \
    do {                                                                      \
        long long e_ = (long long)(expected), a_ = (long long)(actual);       \
        if (e_ != a_) {                                                       \
            printf("  %s:%d: expected 0x%llx, got 0x%llx\n",                  \
                   __FILE__, __LINE__, (unsigned long long)e_,                \
                   (unsigned long long)a_);                                   \
            if (!current_failed) { current_failed = 1; tests_failed++; }      \
        }                                                                     \
    } while (0)

#define DIR_OP_TAB_ADDR      0x00E7FC42
#define DIR_OP_FAMILY_BASE   0x00E7FB9A

/* 0x00E7FC42 - 0x00E7FB9A = 0xA8 = 21 records of 8 bytes. */
TEST(the_bias_is_the_distance_to_the_virtual_base)
{
    ASSERT_EQ(8, sizeof(dir_$op_tab_entry_t));
    ASSERT_EQ(DIR_$OP_TAB_BASE_INDEX * (int)sizeof(dir_$op_tab_entry_t),
              DIR_OP_TAB_ADDR - DIR_OP_FAMILY_BASE);
}

/* Opcodes 0x2A..0x5C -> records 21..46, and the array covers exactly those. */
TEST(the_table_covers_every_opcode_do_op_admits)
{
    ASSERT_EQ(DIR_$OP_TAB_BASE_INDEX, 0x2A >> 1);
    ASSERT_EQ(DIR_$OP_TAB_ENTRIES - 1, (0x5C >> 1) - DIR_$OP_TAB_BASE_INDEX);
    ASSERT_EQ(0xD0, sizeof(DIR_$DATA.op_tab));
    ASSERT_EQ(0x00E7FD12 - DIR_OP_TAB_ADDR, (int)sizeof(DIR_$DATA.op_tab));
}

/*
 * DIR_$ADD_MOUNT reads 0x00E7FD02 / 0x00E7FD06 and DIR_$DROP_MOUNT
 * 0x00E7FD0A / 0x00E7FD0E; both are the last two records.  DIR_$GET_ENTRYU
 * reaches record 34 through A5 as (0x20aa,A5) / (0x20ae,A5) = 0x00E7FCAA /
 * 0x00E7FCAE, whose image words are 0x0000 and 0x0002.
 */
TEST(the_named_records_line_up_with_their_addresses)
{
    const char *base = (const char *)DIR_$DATA.op_tab;

    ASSERT_EQ(0x00E7FD02 - DIR_OP_TAB_ADDR,
              (const char *)&DIR_$OP_REC(0x5A >> 1).version - base);
    ASSERT_EQ(0x00E7FD06 - DIR_OP_TAB_ADDR,
              (const char *)&DIR_$OP_REC(0x5A >> 1).base_size - base);
    ASSERT_EQ(0x00E7FD0A - DIR_OP_TAB_ADDR,
              (const char *)&DIR_$OP_REC(0x5C >> 1).version - base);
    ASSERT_EQ(0x00E7FD0E - DIR_OP_TAB_ADDR,
              (const char *)&DIR_$OP_REC(0x5C >> 1).base_size - base);

    ASSERT_EQ(0x0000, DIR_$OP_REC(0x44 >> 1).version);
    ASSERT_EQ(0x0002, DIR_$OP_REC(0x44 >> 1).base_size);
    ASSERT_EQ(0x000c, DIR_$OP_REC(0x5A >> 1).base_size);
    ASSERT_EQ(0x000c, DIR_$OP_REC(0x5C >> 1).base_size);
}

/*
 * DIR_$DO_OP's (0x1f9c,A0) and (0x1fa0,A0) with A5 = 0x00E7DC00 are record
 * + 0x02 and record + 0x06 of the same records, so the two DIR_$OP_ macros
 * must land two and six bytes into the record.
 */
TEST(do_ops_a5_displacements_are_the_reply_fields)
{
    const char *rec = (const char *)&DIR_$OP_REC(0x30 >> 1);
    ASSERT_EQ(2, (const char *)&DIR_$OP_VERSION(0x30 >> 1) - rec);
    ASSERT_EQ(6, (const char *)&DIR_$OP_REPLY_SIZE(0x30 >> 1) - rec);
    ASSERT_EQ(0, (const char *)&DIR_$OP_REQ_VERSION(0x30 >> 1) - rec);
}

/* 0x00E7FD12..0x00E7FD24, the segment's last 0x12 bytes. */
TEST(the_segment_tail_holds_its_image_bytes)
{
    ASSERT_EQ(0x12, DIR_$DATA_SIZE - __builtin_offsetof(dir_$data_t, seg_tail_pad));
    ASSERT_EQ(0x0000, DIR_$DATA.seg_tail_pad);
    ASSERT_EQ(0x00020001u, DIR_$DATA.readu_cookie_first);
    ASSERT_EQ(0x00010001u, DIR_$DATA.readu_cookie_dotdot);
    ASSERT_EQ(0x00000001u, DIR_$DATA.readu_cookie_dot);
    ASSERT_EQ(0, memcmp(DIR_$DATA.bak_suffix, ".bak", 4));
    /* dir_$do_op_add_bak's 1-based (0x211f,A5,Dn) */
    ASSERT_EQ('.', DIR_$DATA.bak_char[1]);
    ASSERT_EQ('k', DIR_$DATA.bak_char[4]);
}

/* ---------------------------------------------------------------- */
/* The block at its image address                                     */
/* ---------------------------------------------------------------- */

static uint32_t va(const void *p) { return ARCH_PTR_TO_VA(p); }

TEST(size_address_and_a5)
{
    ARCH_HOST_VA_BASE = (uintptr_t)&DIR_$DATA - 0x00E7DBF8u;
    ASSERT_EQ(0x212C, sizeof(dir_$data_t));
    ASSERT_EQ(0x00E7DBF8u, MODULE_DATA_ADDR(DIR_$DATA));
    /* `lea (0xe7dc00).l,A5': the segment + 8; OLD_DIR's A5 follows the block */
    ASSERT_EQ(0x00E7DC00u, MODULE_DATA_ADDR(DIR_$DATA) + DIR_A5_BIAS);
    ASSERT_EQ(0x00E7FD24u, va((const char *)&DIR_$DATA + sizeof(DIR_$DATA)));
    ARCH_HOST_VA_BASE = 0;
}

/* Every symbol the SAU2 map puts in "D E7DBF8 DIR size = 212C". */
TEST(map_symbols_are_fields)
{
    ARCH_HOST_VA_BASE = (uintptr_t)&DIR_$DATA - 0x00E7DBF8u;
    ASSERT_EQ(0x00E7F158u, va(&DIR_$DATA.mttab_count));               /* DIR_$MTTAB */
    ASSERT_EQ(0x00E7FC10u, va(&DIR_$DATA.entry_cache_too_long_name));
    ASSERT_EQ(0x00E7FC14u, va(&DIR_$DATA.entry_cache_skipped_acl));
    ASSERT_EQ(0x00E7FC18u, va(&DIR_$DATA.entry_cache_tries));
    ASSERT_EQ(0x00E7FC1Cu, va(&DIR_$DATA.entry_cache_hits));
    ASSERT_EQ(0x00E7FC20u, va(&DIR_$DATA.hndl_waits));
    ASSERT_EQ(0x00E7FC24u, va(&DIR_$DATA.lk_timeouts));
    ASSERT_EQ(0x00E7FC28u, va(&DIR_$DATA.lk_wait_2));
    ASSERT_EQ(0x00E7FC2Cu, va(&DIR_$DATA.lk_waits));
    ASSERT_EQ(0x00E7FC42u, va(DIR_$DATA.op_tab));                     /* DIR_$OP_TAB */
    ARCH_HOST_VA_BASE = 0;
}

/* The module-local cells and tables, at the addresses the code forms. */
TEST(module_cells_are_where_the_code_reaches_them)
{
    ARCH_HOST_VA_BASE = (uintptr_t)&DIR_$DATA - 0x00E7DBF8u;
    ASSERT_EQ(0x00E7DBF8u, va(&DIR_$DATA.purify_seg_list));    /* A5-0x8 */
    ASSERT_EQ(0x00E7DBFCu, va(&DIR_$DATA.crash_status));       /* A5-0x4 */
    ASSERT_EQ(0x00E7DC00u, va(DIR_$DATA.link_buf));             /* pea (A5) */
    ASSERT_EQ(0x00E7E000u, va(DIR_$DATA.entry_cache));          /* A5+0x400 */
    ASSERT_EQ(0x28, sizeof(DIR_$DATA.entry_cache[0]));
    ASSERT_EQ(0x00E7F280u, va(DIR_$DATA.lock_tab));             /* A5+0x1680 */
    ASSERT_EQ(0x00E7F480u, va(DIR_$DATA.handle_tab));           /* A5+0x1880 */
    ASSERT_EQ(0x00E7F4BCu, va(&DIR_$DATA.handle_tab[1]));       /* free head */
    ASSERT_EQ(0x00E7FC00u, va(DIR_$DATA.name_offset_table));
    ASSERT_EQ(0x00E7FC30u, va(&DIR_$DATA.lock_free));
    ASSERT_EQ(0x00E7FC34u, va(&DIR_$DATA.lock_in_use));
    ASSERT_EQ(0x00E7FC38u, va(&DIR_$DATA.handle_free));
    ASSERT_EQ(0x00E7FC3Cu, va(&DIR_$DATA.handle_in_use));
    ASSERT_EQ(0x00E7FC40u, va(&DIR_$DATA.link_buf_owner));
    ASSERT_EQ(0x00E7FD14u, va(&DIR_$DATA.readu_cookie_first));
    ASSERT_EQ(0x00E7FD20u, va(DIR_$DATA.bak_suffix));
    ARCH_HOST_VA_BASE = 0;
}

/*
 * The one-based tables are union arms declared from their bias slots:
 * element n is A5 + base + n*stride, exactly the displacement the code uses.
 */
TEST(bias_arms_index_with_the_pascal_number)
{
    ARCH_HOST_VA_BASE = (uintptr_t)&DIR_$DATA - 0x00E7DBF8u;
    /* (0x1554,A0), A0 = A5 + n*8 (0x00E5336E) */
    ASSERT_EQ(0x00E7DC00u + 0x1554u + 1 * 8, va(&DIR_$DATA.mount_uid[1]));
    ASSERT_EQ(0x00E7DC00u + 0x1554u + 8 * 8, va(&DIR_$DATA.mount_uid[8]));
    /* element 0's low longword is DIR_$MTTAB's count */
    ASSERT_EQ(va(&DIR_$DATA.mttab_count), va(&DIR_$DATA.mount_uid[0].low));
    /* (0x1594,A1), A1 = A5 + n*8 (0x00E53382) */
    ASSERT_EQ(0x00E7DC00u + 0x1594u + 3 * 8, va(&DIR_$DATA.mount_tgt[3]));
    /* (0x15d8,A2), A2 = A5 + n*4 (0x00E53394) */
    ASSERT_EQ(0x00E7DC00u + 0x15D8u + 5 * 4, va(&DIR_$DATA.mount_node[5]));
    /* (0x15fe,A1), A1 = A5 + pid*2 (0x00E4B128) */
    ASSERT_EQ(0x00E7DC00u + 0x15FEu + 7 * 2, va(&DIR_$DATA.proc_flags[7]));
    ASSERT_EQ(va(DIR_$DATA.lock_tab), va(&DIR_$DATA.proc_flags[PROC1_MAX_PROCESSES]));
    /* (0x211f,A5,Dn) */
    ASSERT_EQ(0x00E7DC00u + 0x211Fu + 2, va(&DIR_$DATA.bak_char[2]));
    /* DIR_$OP_REC's bias: opcode 0x2A >> 1 is the first record */
    ASSERT_EQ(va(&DIR_$DATA.op_tab[0]), va(&DIR_$OP_REC(0x2A >> 1)));
    ARCH_HOST_VA_BASE = 0;
}

/* The image's non-zero bytes, and zero everywhere the code fills in. */
TEST(contents_are_the_images)
{
    size_t i;
    int zero = 1;
    /* A5-0x8 / A5-0x4: `00 e4 b3 3c 00 e4 b2 30' (host: the image VAs) */
    ASSERT_EQ(0x00E4B33Cu, DIR_$DATA.purify_seg_list);
    ASSERT_EQ(0x00E4B230u, DIR_$DATA.crash_status);
    ASSERT_EQ(0, DIR_$DATA.name_offset_table[0]);
    ASSERT_EQ(4, DIR_$DATA.name_offset_table[1]);
    ASSERT_EQ(16, DIR_$DATA.name_offset_table[2]);
    ASSERT_EQ(20, DIR_$DATA.name_offset_table[3]);
    ASSERT_EQ(12, DIR_$DATA.name_offset_table[4]);
    ASSERT_EQ(0x000e, DIR_$DATA.op_tab[0].base_size);         /* 0x00E7FC46 */
    ASSERT_EQ(0x0001, DIR_$DATA.op_tab[23].reply_version);    /* 0x00E7FCFC */
    for (i = 0; i < sizeof(DIR_$DATA.link_buf); i++) zero &= DIR_$DATA.link_buf[i] == 0;
    for (i = __builtin_offsetof(dir_$data_t, entry_cache);
         i < __builtin_offsetof(dir_$data_t, name_offset_table); i++) {
        zero &= ((const uint8_t *)&DIR_$DATA)[i] == 0;
    }
    for (i = __builtin_offsetof(dir_$data_t, entry_cache_too_long_name);
         i < __builtin_offsetof(dir_$data_t, op_tab); i++) {
        zero &= ((const uint8_t *)&DIR_$DATA)[i] == 0;
    }
    ASSERT_EQ(1, zero);
}

/* DIR_$CRASH_STATUS is the cell's contents, not the constant's address. */
TEST(crash_status_is_the_cells_contents)
{
    ASSERT_EQ((uintptr_t)ARCH_VA_TO_PTR(DIR_$DATA.crash_status),
              (uintptr_t)DIR_$CRASH_STATUS);
}

/* `move.w (0x155a,A5)' is the low word of the DIR_$MTTAB longword. */
TEST(mount_count16_is_the_low_word)
{
    int32_t saved = DIR_$DATA.mttab_count;
    ASSERT_EQ(0, saved);
    DIR_$DATA.mttab_count = 0x00010003;
    ASSERT_EQ(3, DIR_MOUNT_COUNT16());
    DIR_$DATA.mttab_count = saved;
}

int main(void)
{
    printf("=== DIR module block tables ===\n");
    RUN_TEST(the_bias_is_the_distance_to_the_virtual_base);
    RUN_TEST(the_table_covers_every_opcode_do_op_admits);
    RUN_TEST(the_named_records_line_up_with_their_addresses);
    RUN_TEST(do_ops_a5_displacements_are_the_reply_fields);
    RUN_TEST(the_segment_tail_holds_its_image_bytes);
    RUN_TEST(size_address_and_a5);
    RUN_TEST(map_symbols_are_fields);
    RUN_TEST(module_cells_are_where_the_code_reaches_them);
    RUN_TEST(bias_arms_index_with_the_pascal_number);
    RUN_TEST(contents_are_the_images);
    RUN_TEST(crash_status_is_the_cells_contents);
    RUN_TEST(mount_count16_is_the_low_word);
    printf("%d tests, %d failed\n", tests_run, tests_failed);
    return tests_failed != 0;
}
